import {MatchersV3, PactV3} from '@pact-foundation/pact';
import axios from 'axios';
import path from 'path';


const { like, eachLike, regex } = MatchersV3;

const provider = new PactV3({
  consumer: 'martech-theloophub-mfe',
  provider: 'martech-oneway-reports-bff',
  dir: path.resolve(process.cwd(), 'pacts'),
  logLevel: 'warn',
});

interface BrandData {
    src: string;
    name: string;
    variation: number;
    variationMeasure: string;
    variationDirection: 'up' | 'down';
    country: string;
    country_src: string;
  }
interface CellValue {
    unitMeasure?: string;
    value: number | string | { brands: BrandData[] };
    variationDirection?: 'up' | 'down';
    marginBottom?: boolean;
    radiusRight?: boolean;
    radiusTop?: boolean;
  }
interface TableHeader {
    title: string;
    id: string;
    subtitle?: string;
    children?: Array<{ id: string; title: string }>;
  }
interface PortfolioTableData {
    header: TableHeader[];
    rows: CellValue[][];
    splits: string[][];
  }
interface BffComponent {
    id: string;
    type?: string;
    data: {
      portfolioPerformance?: PortfolioTableData;
      [key: string]: any;
    };
  }
interface PortfolioPerformanceResponse {
    view: string;
    components: BffComponent[];
    compressed?: boolean;
  }

function bffClient(mockUrl: string) {
    return {
      getPortfolioPerformance: async (params: {
        zone: string;
        country: string;
        dt_ini: string;
        dt_end: string;
        period: 'YTD' | 'Month';
        viewtype?: string;
      }) => {
        // Simular a normalização de params que BffService faz
        const normalizedParams = {
          'filter[zone]': params.zone,
          'filter[country]': params.country,
          'filter[dt_ini]': params.dt_ini,
          'filter[dt_end]': params.dt_end,
          'filter[period]': params.period,
          ...(params.viewtype ? { 'filter[viewtype]': params.viewtype } : {}),
        };
  
        return axios.get<PortfolioPerformanceResponse>(
          `${mockUrl}/views/value-creation_portfolio-performance_overview_overview`,
          { params: normalizedParams }
        );
      },
    };
  }
  
// O que estamos fazendo:
// - Definir o padrão esperado para UMA linha de portfolio

const portfolioRowMatcher = {
    portfolio: {
      marginBottom: like(true),
      value: like('Megabrands'),  // ← Qualquer portfolio name
    },
    volume_growth_contr: {
      unitMeasure: '%',
      value: like(49.1),  // ← Qualquer número
    },
    volume_weight: {
      unitMeasure: '%',
      value: like(60.9),
    },
    volume_vs_ly: {
      unitMeasure: '%',
      value: like(1.3),
      variationDirection: like('up'),  // ← 'up' ou 'down'
    },
    net_revenue_vs_ly: {
      unitMeasure: '%',
      value: like(7.3),
      variationDirection: like('up'),
    },
    cores_vs_ly: {
      unitMeasure: '%',
      value: like(8.2),
      variationDirection: like('up'),
    },
    brand_power_vs_ly: {
      unitMeasure: 'pp',
      value: like(0.8),
      variationDirection: like('up'),
    },
    sm_of_maco: {
      unitMeasure: '%',
      value: like(13.8),
    },
    sm_weight: {
      unitMeasure: '%',
      value: like(59),
    },
    brands_vol_og_vs_ly: {
      brands: eachLike({
        src: like('https://onewaymartech-assets.mybees-platform.com/brands/corona/square.png'),
        name: like('Corona'),
        variation: like(6),
        variationMeasure: '%',
        variationDirection: like('up'),
        country: like('ABI'),
        country_src: like('https://onewaymartech-assets.mybees-platform.com/countries/rounded_flags/ABI.png'),
      }, { min: 0 }),  // ← Pode ter 0+ brands
      value: '_brands',
    },
  };
  
// - Validar TODA a resposta BFF
// - Incluir view correto
// - Incluir components com estrutura correta
// - Incluir array de portfolios

const portfolioPerformanceResponseMatcher = {
    view: 'value-creation_portfolio-performance_overview_overview',
    components: eachLike({
      id: 'portfolioPerformance',
      data: {
        header: eachLike({
          title: like('Portfolio'),
          id: like('portfolio'),
          subtitle: like(''),
          children: eachLike({
            id: like('volume_growth_contr'),
            title: like('Growth Contrib.'),
          }, { min: 0 }),
        }, { min: 1 }),
        
        rows: eachLike(
          eachLike(portfolioRowMatcher, { min: 1 }),
          { min: 2 }  // ← Mínimo 2: portfolios + total
        ),
        
        splits: eachLike(
          eachLike(like('Portfolio'))
        ),
      },
    }, { min: 1 }),
  };
  
  // ─── O que isso valida:
  // - Resposta começa com view correto
  // - Tem 1+ components
  // - Cada component tem header, rows e splits
  // - Rows tem mínimo 2 linhas (portfolios + total)
  // - Cada linha é array de cells com struktura correta

  describe('MFE → BFF | GET /views (Portfolio Performance) - Global', () => {
    it('retorna portfolios com dados completos para zona global (ABI)', async () => {
      // ────────────────────────────────────────────────────────────────
      // GIVEN (Precondição):
      // "Existe dados de portfolio performance para zona ABI"
      // ────────────────────────────────────────────────────────────────
      await provider
        .given('portfolio performance data exists for zone ABI')
        
        // ────────────────────────────────────────────────────────────────
        // UPON RECEIVING (Descrição da requisição):
        // "MFE faz GET na rota de portfolio performance com filtros ABI"
        // ────────────────────────────────────────────────────────────────
        .uponReceiving('GET /views portfolio performance for zone ABI and country ABI')
        
        // ────────────────────────────────────────────────────────────────
        // WITH REQUEST (O que o MFE envia):
        // - Método: GET (só leitura, idempotente)
        // - Path: /views/value-creation_portfolio-performance_overview_overview
        // - Query params: Normalizados como filter[key]=value
        // ────────────────────────────────────────────────────────────────
        .withRequest({
          method: 'GET',
          path: '/views/value-creation_portfolio-performance_overview_overview',
          query: {
            'filter[zone]': 'ABI',
            'filter[country]': 'ABI',
            'filter[dt_ini]': '2026-01-01',
            'filter[dt_end]': '2026-06-01',
            'filter[period]': 'YTD',
          },
        })
        
        // ────────────────────────────────────────────────────────────────
        // WILL RESPOND WITH (O que o BFF deve retornar):
        // - Status: 200 OK
        // - Headers: Content-Type JSON
        // - Body: Estrutura validada por matchers
        // ────────────────────────────────────────────────────────────────
        .willRespondWith({
          status: 200,
          headers: { 'Content-Type': 'application/json' },
          body: portfolioPerformanceResponseMatcher,
        })
        
        // ────────────────────────────────────────────────────────────────
        // EXECUTE TEST (Fazer a chamada e validar):
        // - Usar o helper client para chamar mock server
        // - Validar status 200
        // - Validar estrutura de resposta
        // - Validar que dados não estão vazios
        // ────────────────────────────────────────────────────────────────
        .executeTest(async (mockServer) => {
          const { data, status } = await bffClient(mockServer.url)
            .getPortfolioPerformance({
              zone: 'ABI',
              country: 'ABI',
              dt_ini: '2026-01-01',
              dt_end: '2026-06-01',
              period: 'YTD',
            });
  
          // ✓ Validação 1: HTTP status correto
          expect(status).toBe(200);
  
          // ✓ Validação 2: View correto
          expect(data.view).toBe('value-creation_portfolio-performance_overview_overview');
  
          // ✓ Validação 3: Tem components
          expect(data.components).toHaveLength(1);
          expect(data.components[0].id).toBe('portfolioPerformance');
  
          // ✓ Validação 4: Dados não vazios
          const portfolioData = data.components[0].data;
          expect(portfolioData.header).not.toHaveLength(0);
          expect(portfolioData.rows).not.toHaveLength(0);
  
          // ✓ Validação 5: Tem múltiplos portfolios + linha total
          const portfolioRows = portfolioData.rows[0]; // Primeiro array é os portfolios
          const totalRow = portfolioData.rows[1];      // Segundo array é total
          expect(portfolioRows.length).toBeGreaterThanOrEqual(4); // Megabrands, Expansion, Sustain, Tail
          expect(totalRow[0].portfolio.value).toBe('Total');
  
          // ✓ Validação 6: Cada portfolio tem brands
          portfolioRows.forEach((row) => {
            expect(row.brands_vol_og_vs_ly.brands).toBeDefined();
            expect(Array.isArray(row.brands_vol_og_vs_ly.brands)).toBe(true);
          });
  
          // ✓ Validação 7: Estrutura de splits
          expect(portfolioData.splits).toContainEqual(['Portfolio']);
          expect(portfolioData.splits).toContainEqual(['Volume']);
        });
    });
  });
  
  // ────────────────────────────────────────────────────────────────
  // RESUMO DO QUE FOI TESTADO:
  // ────────────────────────────────────────────────────────────────
  // 1. Request é enviado com parâmetros corretos
  // 2. Response tem status 200
  // 3. Response tem estrutura de BFF (view + components)
  // 4. Component contém dados de portfolio performance
  // 5. Múltiplos portfolios são retornados
  // 6. Cada portfolio tem brands associadas
  // 7. Linha de total é calculada
  // ────────────────────────────────────────────────────────────────